class ExpressionWrapper(Expression):
    """
    An expression that can wrap another expression so that it can provide
    extra context to the inner expression, such as the output_field.
    """

    def __init__(self, expression, output_field):
        super().__init__(output_field=output_field)
        self.expression = expression

    def set_source_expressions(self, exprs):
        self.expression = exprs[0]

    def get_source_expressions(self):
        return [self.expression]

    def as_sql(self, compiler, connection):
        # Check if the inner expression is a constant (like Value)
        if isinstance(self.expression, Value):
            # If it's a Value expression (constant), return just the SQL for the expression
            # without including it in GROUP BY
            return self.expression.as_sql(compiler, connection)
        else:
            # For non-constant expressions, delegate to the original method
            return self.expression.as_sql(compiler, connection)

    def __repr__(self):
        return f'{self.__class__.__name__}({self.expression})'

